    createPromptButton.onclick=openCreator;importPairButton.onclick=()=>pairInput.click();pairInput.onchange=async()=>{const files=[...pairInput.files];try{status.textContent='Đang kiểm tra cặp ảnh và metadata…';await handlePairImport(files);}catch(error){status.textContent=`Không nhập được cặp tệp: ${error.message}`;}finally{pairInput.value='';}};metadataInput.onchange=async()=>{const file=metadataInput.files?.[0],target=this.pendingMetadataTarget;this.pendingMetadataTarget=null;if(!file||!target)return;try{status.textContent=`Đang kiểm tra metadata cho ${target.display_name}…`;await handlePairImport([file],target);}catch(error){status.textContent=`Không nhập được metadata: ${error.message}`;}finally{metadataInput.value='';}};refresh();return{close:dismiss,refresh};
